// Function to check if a single number is even
fn is_even(n: u32) -> bool {
    n % 2 == 0
}

// Function to execute the even check for a single number
fn is_even_exec(n: u32) -> bool {
    is_even(n)
}

// Function to check if there is at least one even number in the array
fn is_product_even(arr: &Vec<u32>) -> bool {
    for &num in arr.iter() {
        if is_even(num) {
            return true; // Return true if an even number is found
        }
    }
    false // Return false if no even number is found
}

// Example usage
fn main() {
    let numbers = vec![1, 3, 5, 7, 8];
    println!("Contains even number: {}", is_product_even(&numbers)); // Should print true

    let empty_numbers: Vec<u32> = vec![];
    println!("Contains even number: {}", is_product_even(&empty_numbers)); // Should print false
}